    slope=sum((x-mx)*(v-my) for x,v in zip(xs,y))/den if den else 0
    return y[-1]+slope

def shc_pred(vals, m=3):
    # Treated pre = last m. Historical donors: earlier m-pre blocks with following pseudo-post.
    target=vals[-m:]
